svg.script:
(function(){
  var knot = document.getElementById('knot');
  var win = (typeof window !== 'undefined' && window.parent && window.parent !== window) ? window.parent : window;
  var raf = null;
  function buildPath(delta){
    var cx=30, cy=30, sx=22, sy=22, a=7, b=6, N=280, d='';
    for (var i=0; i<=N; i++){
      var t = (i/N) * Math.PI * 2;
      var x = cx + sx * Math.sin(a * t + delta);
      var y = cy + sy * Math.sin(b * t);
      d += (i===0 ? 'M ' : ' L ') + x.toFixed(2) + ',' + y.toFixed(2);
    }
    return d;
  }
  function paint(){
    var y = win.scrollY || 0;
    knot.setAttribute('d', buildPath(y * 0.008));
  }
  win.addEventListener('scroll', function(){
    if (raf) cancelAnimationFrame(raf);
    raf = requestAnimationFrame(paint);
  }, { passive: true });
  paint();
})();
